'use client'

import { useId, useRef } from 'react'
import type { ReactNode } from 'react'
import { useEffectPropSignal, useSignalEffect } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import styles from './sheet.module.css'

export interface SheetProps {
  open: boolean
  onClose: () => void
  /** Optional heading. Accepts rich nodes; when present it labels the dialog via `aria-labelledby`. */
  title?: ReactNode
  children: ReactNode
  /**
   * Edge the sheet slides in from: `end` (the inline end — right in LTR), `start`, `top` or
   * `bottom`.
   *
   * @defaultValue `end`
   * @see the component manifest
   */
  side?: 'start' | 'end' | 'top' | 'bottom'
}

export function Sheet({ open, onClose, title, children, side = 'end' }: SheetProps) {
  const sheetRef = useRef<HTMLDivElement>(null)
  const titleId = useId()
  const isOpen = useEffectPropSignal(open)
  const onCloseRef = useRef(onClose)
  onCloseRef.current = onClose

  useSignalEffect(() => {
    const el = sheetRef.current
    if (!el) return
    if (isOpen.value) {
      try {
        el.showPopover()
      } catch {
        /* noop */
      }
    } else {
      try {
        el.hidePopover()
      } catch {
        /* noop */
      }
    }
  })

  return (
    <div
      ref={sheetRef}
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      popover="manual"
      role="dialog"
      aria-modal="true"
      aria-labelledby={title != null ? titleId : undefined}
      data-state={open ? 'open' : 'closed'}
      data-side={side}
      className={styles.sheet}
    >
      <div className={styles.header}>
        {title != null && (
          <span id={titleId} className={styles.title}>
            {title}
          </span>
        )}
        <button
          type="button"
          aria-label={t(builtin.sheet.close)}
          onClick={() => onCloseRef.current()}
          className={styles.close}
        >
          ✕
        </button>
      </div>
      <div className={styles.body} data-cascivo-sheet-body="">
        {children}
      </div>
    </div>
  )
}

@layer cascivo.component {
  .sheet {
    position: fixed;
    margin: 0;
    padding: 0;
    border: none;
    background: var(--cascivo-color-surface);
    box-shadow: var(--cascivo-shadow-overlay);
    /* `display` belongs to the OPEN state only — see multi-select.module.css for the
       full note. An author `display` here beats the UA
       `[popover]:not(:popover-open) { display: none }` rule, so a closed sheet keeps a
       full-height, fixed-position, invisible box over the page and eats every click
       (2026-07-28 report C13). Enforced by `pnpm popover:check`. */
    flex-direction: column;

    &:popover-open {
      display: flex;
    }

    /* Transitions for enter/exit */
    transition:
      translate var(--cascivo-motion-enter),
      display var(--cascivo-motion-enter) allow-discrete,
      overlay var(--cascivo-motion-enter) allow-discrete;

    &[data-state='closed'] {
      transition:
        translate var(--cascivo-motion-exit),
        display var(--cascivo-motion-exit) allow-discrete,
        overlay var(--cascivo-motion-exit) allow-discrete;
    }

    /* Side: end (right) */
    &[data-side='end'] {
      inset-block: 0;
      inset-inline-end: 0;
      width: min(24rem, 90vw);
      height: 100%;
      border-inline-start: 1px solid var(--cascivo-color-border);
      border-radius: var(--cascivo-radius-overlay) 0 0 var(--cascivo-radius-overlay);
      translate: 100% 0;

      &[data-state='open'] {
        translate: 0 0;
      }

      @starting-style {
        &[data-state='open'] {
          translate: 100% 0;
        }
      }
    }

    /* Side: start (left) */
    &[data-side='start'] {
      inset-block: 0;
      inset-inline-start: 0;
      width: min(24rem, 90vw);
      height: 100%;
      border-inline-end: 1px solid var(--cascivo-color-border);
      border-radius: 0 var(--cascivo-radius-overlay) var(--cascivo-radius-overlay) 0;
      translate: -100% 0;

      &[data-state='open'] {
        translate: 0 0;
      }

      @starting-style {
        &[data-state='open'] {
          translate: -100% 0;
        }
      }
    }

    /* Side: top */
    &[data-side='top'] {
      inset-inline: 0;
      inset-block-start: 0;
      width: 100%;
      height: auto;
      max-height: 80vh;
      border-block-end: 1px solid var(--cascivo-color-border);
      border-radius: 0 0 var(--cascivo-radius-overlay) var(--cascivo-radius-overlay);
      translate: 0 -100%;

      &[data-state='open'] {
        translate: 0 0;
      }

      @starting-style {
        &[data-state='open'] {
          translate: 0 -100%;
        }
      }
    }

    /* Side: bottom */
    &[data-side='bottom'] {
      inset-inline: 0;
      inset-block-end: 0;
      width: 100%;
      height: auto;
      max-height: 80vh;
      border-block-start: 1px solid var(--cascivo-color-border);
      border-radius: var(--cascivo-radius-overlay) var(--cascivo-radius-overlay) 0 0;
      translate: 0 100%;

      &[data-state='open'] {
        translate: 0 0;
      }

      @starting-style {
        &[data-state='open'] {
          translate: 0 100%;
        }
      }
    }

    &::backdrop {
      background-color: rgb(0 0 0 / 0.4);
      opacity: 1;
      transition:
        opacity var(--cascivo-motion-enter),
        display var(--cascivo-motion-enter) allow-discrete,
        overlay var(--cascivo-motion-enter) allow-discrete;

      @starting-style {
        opacity: 0;
      }
    }

    &[data-state='closed']::backdrop {
      opacity: 0;
      transition:
        opacity var(--cascivo-motion-exit),
        display var(--cascivo-motion-exit) allow-discrete,
        overlay var(--cascivo-motion-exit) allow-discrete;
    }
  }

  .header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--cascivo-space-4) var(--cascivo-space-6);
    border-block-end: 1px solid var(--cascivo-color-border);
    flex-shrink: 0;
  }

  .title {
    font-size: var(--cascivo-text-lg);
    font-weight: var(--cascivo-font-semibold);
    color: var(--cascivo-color-text);
  }

  .close {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    padding: 0;
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-muted);
    background: transparent;
    border: none;
    border-radius: var(--cascivo-radius-control);
    cursor: pointer;
    transition:
      color var(--cascivo-duration-150) var(--cascivo-ease-out),
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover {
      color: var(--cascivo-color-text);
      background-color: var(--cascivo-color-bg-subtle);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }
  }

  .body {
    /* See modal.module.css for the rationale; the dialog family shares one gap token. */
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-dialog-body-gap, var(--cascivo-space-5));
    padding: var(--cascivo-space-6);
    overflow-y: auto;
    flex: 1;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Sheet',
  description: 'Slide-in panel from any edge, using popover=manual and @starting-style animations',
  category: 'overlay',
  clientJs: 'required',
  states: ['open', 'closed'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'open',
      description: 'Whether the component is open (controlled).',
      type: 'boolean',
      required: true,
    },
    {
      name: 'onClose',
      description: 'Called when the component is closed.',
      type: '() => void',
      required: true,
    },
    {
      name: 'title',
      description: 'Title text for the component.',
      type: 'React.ReactNode',
      required: false,
    },
    {
      name: 'side',
      description:
        'Edge the sheet slides in from: `end` (the inline end — right in LTR), `start`, `top` or `bottom`.',
      type: "'start' | 'end' | 'top' | 'bottom'",
      required: false,
      default: 'end',
    },
  ],
  tokens: [
    '--cascivo-dialog-body-gap',
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-radius-lg',
    '--cascivo-shadow-xl',
    '--cascivo-motion-enter',
    '--cascivo-motion-exit',
  ],
  accessibility: {
    role: 'dialog',
    wcag: '2.2-AA',
    keyboard: ['Escape', 'Tab', 'Shift+Tab'],
  },
  examples: [
    {
      title: 'Basic',
      code: `<Sheet open={isOpen} onClose={() => setIsOpen(false)} title="Filters">
  <FilterForm />
</Sheet>`,
    },
    {
      title: 'Bottom sheet',
      code: `<Sheet open={isOpen} onClose={close} side="bottom" title="Share">
  <ShareOptions />
</Sheet>`,
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  styleHooks: ['data-cascivo-sheet-body'],
  tags: ['overlay', 'drawer', 'panel', 'slide'],
  intent: {
    whenToUse: [
      'Showing secondary content or a form in a panel that slides in from a screen edge',
      'Navigation, filters, or detail views that benefit from full-height side space without leaving the page',
      'Mobile-friendly drawers where a centered modal would feel cramped',
    ],
    whenNotToUse: [
      'A short confirmation or focused decision — use Modal or AlertDialog',
      'Small contextual content anchored to a trigger — use Popover',
    ],
    antiPatterns: [
      {
        bad: '<Sheet title="Delete item?">Are you sure?</Sheet>',
        good: '<AlertDialog title="Delete item?" />',
        why: 'A full edge-to-edge panel is overkill for a yes/no decision; AlertDialog is the right scale and semantics',
      },
    ],
    related: [
      {
        name: 'Modal',
        relationship: 'alternative',
        reason: 'Use for centered, focused dialogs rather than edge panels',
      },
      {
        name: 'Popover',
        relationship: 'alternative',
        reason: 'Use for small content anchored to a trigger element',
      },
    ],
    a11yRationale:
      'Uses popover="manual" with role="dialog" and aria-modal so it is announced as a modal surface; when a title is provided it labels the dialog via aria-labelledby (so rich title nodes stay accessible), and Escape/Tab handling comes from the popover platform behavior.',
    flexibility: [
      {
        area: 'side',
        level: 'strict',
        note: 'Limited to start | end | top | bottom — drives the slide direction and animation',
      },
      {
        area: 'body content',
        level: 'flexible',
        note: 'Any children; consumer owns the panel contents',
      },
    ],
  },
}
